/// <summary>
/// PricingAttribute of table <c>InventTable</c> field BOMUnitId.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventTableBOMUnitId extends UPSPricingAttributeInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTable, BOMUnitId);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::String);
    InventTable inventTable;
    while select BOMUnitId from inventTable
        group by BOMUnitId
    {
        ret.add(inventTable.BOMUnitId);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventTable, BOMUnitId));
    qbr.value(queryValue(_value));
}
